contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 mAssetAmount) public payable {
        require(to != address(0), "zero beneficiary");
        require(mAssetAmount > 0, "zero amount");

        uint256 beforeCredits = c.imBalances(to);
        uint256 beforeValue = c.balanceOfToken(to);

        (bool ok, bytes memory data) = address(c).call(
