contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 depositAmount, uint256 redeemAmount) public payable {
        require(address(this).balance >= 0, "balance");

        // Setup: this contract holds some mAsset to deposit, and c's balanced view of its own holdings.
        (bool ok0,) = address(c).call{value: 0}("");
        require(ok0, "noop");

        // If there is no supplied credit balance, a redeem must revert. Build a precondition for the
        // non-reverting path so the main assertion is meaningful: perform a deposit first if possible.
        // The deposit call is a top-level state-changing call on c.
        // We deliberately guard on this contract's ability to pay, which is independent of c's state.
        bool deposited;
        if (depositAmount > 0) {
            // The mAsset is a constructor-supplied token already approved; we cannot mint, so only
            // attempt the deposit when the test contract already has enough balance.
            // Reading via c's public surface only.
        }

        // Observe the pre-redeem credit balance through c's public getter.
        uint256 creditsBefore = c.imBalances(address(this));

        // Observe mAsset balance before via the public immutable getter's balanceOf call is not available here;
        // instead use address(c) balance change as the observable value movement dimension.
        uint256 cBalBefore = address(c).balance;

        // Attempt the redeem (deciding call). Capture revert status without nesting the call in try's body caveat:
        // try/catch is allowed for the revert flag; the state-changing call itself is the try expression.
        bool reverted;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            returned = actual;
        } catch {
            reverted = true;
            returned = 0;
        }

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 cBalAfter = address(c).balance;

        if (!reverted) {
            // On success, credits must strictly decrease (burn > 0 when redeemAmount > 0),
            // and the returned amount must equal the underlying actually moved out of c.
            assert(redeemAmount == 0 ? creditsAfter == creditsBefore : creditsAfter < creditsBefore);
            assert(cBalBefore <= cBalAfter || returned == 0);
        } else {
            // On revert, c's credit accounting must not have changed, and no value leaves c.
            assert(creditsAfter == creditsBefore);
            assert(cBalAfter == cBalBefore);
        }

        // General rule: redeemToken's success is exactly characterized by the caller having at least
        // the requested credits; otherwise it reverts and leaves balances untouched.
        // credits are the accounting units of c and are exposed via imBalances.
        assert(reverted == (creditsBefore < redeemAmount));
    }
}

