contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, address to, uint256 redeemAmount) public {
        require(to != address(0), "to must be nonzero");
        require(supplyAmount > 0, "supply must be > 0");

        c.supplyTokenTo(supplyAmount, to);

        uint256 creditsBefore = c.imBalances(to);
        uint256 balanceBefore = address(c).balance;

        (bool redeemReverted, bytes memory redeemData) = address(c).call(
            abi.encodeWithSignature("redeemToken(uint256)", redeemAmount)
        );
        require(!redeemReverted, "redeem reverted unexpectedly");
        uint256 mAssetsActual = abi.decode(redeemData, (uint256));

        uint256 creditsAfter = c.imBalances(to);
        uint256 balanceAfter = address(c).balance;

        assert(creditsBefore >= creditsAfter);
        assert(balanceBefore >= balanceAfter);
        assert(mAssetsActual == balanceBefore - balanceAfter);
        assert(creditsBefore >= creditsAfter);
        assert(mAssetsActual <= supplyAmount);
    }

    receive() external payable {}
}

