contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mAssetAmount, address beneficiary) public payable {
        require(mAssetAmount > 0);
        require(beneficiary != address(0));

        address token = c.depositToken();
        require(token != address(0));
        require(AddressMinimal.isContract(token), "token not a contract");

        uint256 before = c.imBalances(beneficiary);
        require(before == 0, "beneficiary already has credits");

        IERC20(token).transfer(address(c), mAssetAmount);

        uint256 balBefore = IERC20(token).balanceOf(address(c));
        require(balBefore >= mAssetAmount, "mAsset not funded");

        c.supplyTokenTo(mAssetAmount, beneficiary);

        uint256 afterBal = c.imBalances(beneficiary);
        assert(afterBal > before);
    }
}

// minimal internal helper contract just for isContract check
contract AddressMinimal {
    function isContract(address a) internal view returns (bool) {
        return a.code.length > 0;
    }
}

contract InvMutTest {
