contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 depositAmount, uint256 redeemAmount) public payable {
        // Need tokens to deposit and only meaningful when we have something to work with.
        require(depositAmount > 0, "need non-zero deposit");

        // Bring in mAsset by using the mAsset amount directly; c must already own the mAsset.
        // Use the test's own token balance, not msg.value logic.
        IERC20 mAsset = c.mAsset();

        // Capture balance before; only fund the test with its current balance to avoid underflow.
        uint256 testBalance = mAsset.balanceOf(address(this));
        require(testBalance >= depositAmount, "test lacks mAsset");

        // Approve c to pull tokens from the test contract.
        mAsset.approve(address(c), depositAmount);

        // Make the first state-changing call: supply tokens to this test contract.
        c.supplyTokenTo(depositAmount, address(this));

        uint256 credits = c.imBalances(address(this));

        // Second state-changing call: attempt the redeem. May revert when credits are insufficient.
        bool redeemedOk;
        try c.redeemToken(redeemAmount) {
            redeemedOk = true;
        } catch {
            redeemedOk = false;
        }

        uint256 creditsAfter = c.imBalances(address(this));

        // General rule: if the redeem succeeded, the burned credits must not exceed
        // the redeemer's pre-existing credit balance; the only way a burn exceeds that
        // is an underflow, which must be impossible.
        if (redeemedOk) {
            assert(creditsAfter <= credits);
        } else {
            assert(creditsAfter == credits);
        }
    }
}

