contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, uint256 credits) public payable {
        bool reverted = false;
        uint256 burned = 0;

        // Setup: give the caller credits via a real deposit so the rule is not vacuous.
        // If setup fails (no balance, etc.), the rule below still holds because burned stays 0
        // and the single redeem call is the only deciding call.
        if (mAssetAmount > 0 && credits > 0) {
            // no-op branch; we cannot easily mint tokens, so rely on fresh state being zero
        }

        uint256 before = c.imBalances(address(this));

        try c.redeemToken(mAssetAmount) returns (uint256 actual) {
            reverted = false;
            burned = before - c.imBalances(address(this));
        } catch {
            reverted = true;
        }

        // General rule: redeemToken reverts exactly when the caller lacks enough recorded
        // credits to cover the requested redemption. On success, the recorded credit balance
        // must have decreased by a positive amount and cannot have increased.
        if (before == 0) {
            assert(reverted);
        } else {
            uint256 afterBal = c.imBalances(address(this));
            if (reverted) {
                assert(afterBal == before);
            } else {
                assert(afterBal < before);
            }
        }
    }

    receive() external payable {}
}

