contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "zero to");

        uint256 beforeImBalances = c.imBalances(to);

        // Any state-changing call must be its own top-level statement.
        // supplyTokenTo pulls mAssetAmount from this contract and credits `to`.
        // It is exercised only if this test holds enough mAsset.
        bool canSupply = true;
        {
            (bool ok, bytes memory data) = address(c.mAsset()).staticcall(
                abi.encodeWithSignature("balanceOf(address)", address(this))
            );
            if (!ok || data.length < 32) {
                canSupply = false;
            } else {
                uint256 bal = abi.decode(data, (uint256));
                if (bal < mAssetAmount) {
                    canSupply = false;
                }
            }
        }

        uint256 exchangeRate = c.savings().exchangeRate();

        uint256 expectedBefore = (beforeImBalances * exchangeRate) / 1e18;

        // Read balanceOfToken before the supply; view call is allowed anywhere.
        uint256 balBefore = c.balanceOfToken(to);

        bool supplied;
        if (canSupply) {
            bool reverted;
            try c.supplyTokenTo(mAssetAmount, to) {
                reverted = false;
            } catch {
                reverted = true;
            }
            supplied = !reverted;
        }

        uint256 afterImBalances = c.imBalances(to);
        uint256 balAfter = c.balanceOfToken(to);
        uint256 rateAfter = c.savings().exchangeRate();

        uint256 expectedAfter = (afterImBalances * rateAfter) / 1e18;

        // General rule:
        // - balanceOfToken(addr) always equals imBalances(addr) * exchangeRate / 1e18
        // - a successful supplyTokenTo cannot decrease the recipient's credit balance
        // - the old view value was consistent with the old credit balance
        assert(
            balAfter == expectedAfter &&
            balBefore == expectedBefore &&
            afterImBalances >= beforeImBalances &&
            (supplied || afterImBalances == beforeImBalances || !supplied)
        );
    }
}

