contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amt, address beneficiary, uint256 redeemHint) public {
        require(beneficiary != address(0), "beneficiary is zero");
        require(amt > 0, "amount is zero");

        address tokenAddr;
        address mAssetAddr;
        uint256 balanceBefore;
        uint256 balanceAfter;
        bool depositReverted;
        bool redeemReverted;

        (tokenAddr) = c.depositToken();
        mAssetAddr = tokenAddr;
        require(tokenAddr != address(0), "underlying token is zero");

        // Read beneficiary's balance before the deposit using the public getter.
        balanceBefore = c.balanceOfToken(beneficiary);

        // Ensure we have enough balance to transfer: mint to this contract first
        // by way of calling c only through public surface: we transfer from this
        // contract, so this contract must hold the mAsset.
        // We can obtain the mAsset only through a deposit, so we fund this contract
        // by impersonating the underlying token is not possible without an external
        // token.  We instead use the ERC20 mint via a low-level call to a helper
        // is disallowed.  Therefore we drive a deposit from this contract only if
        // this contract already holds enough mAsset; we require the caller to have
        // pre-funded this contract through the constructor/test setup is not possible
        // either.  Instead, we test the guarantee on the deposit side by first
        // checking the balance and then attempting the call, catching revert.

        try c.supplyTokenTo(amt, beneficiary) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        balanceAfter = c.balanceOfToken(beneficiary);

        // If the deposit succeeded, the beneficiary's reported mAsset balance
        // must be at least as large as before: deposits credit the beneficiary.
        if (!depositReverted) {
            assert(balanceAfter >= balanceBefore);
        } else {
            // If the deposit reverted, the beneficiary's balance must be unchanged.
            assert(balanceAfter == balanceBefore);
        }

        // Now test redeem effect: redeem some credits from the beneficiary's
        // perspective.  We use the public getter to see the beneficiary's balance
        // and attempt to redeem as the caller (this contract) from the beneficiary's
        // account is not possible through redeemToken (it redeems msg.sender's own
        // credits).  So the redeem part is not exercised here; the rule we assert
        // is only about the supply-direction guarantee, which is the one the
        // contract must always satisfy.
    }

    receive() external payable {}
}

