        require(c.mAsset().balanceOf(address(this)) >= supplyAmount, "insufficient mAsset balance");

        // approve and supply to depositor
        c.mAsset().approve(address(c), supplyAmount);
        c.supplyTokenTo(supplyAmount, depositor);

        // record depositor's credits before the redeem attempt
        uint256 creditsBefore = c.imBalances(depositor);

        // attempt a redeem by the test contract itself, which should have no credits
        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the redeem succeeded, the depositor's credits must be unchanged
        // (since msg.sender != depositor had no credits and should not alter depositor's balance).
        // If the redeem reverted, the depositor's credits must also be unchanged.
        uint256 creditsAfter = c.imBalances(depositor);
        assert(creditsAfter >= creditsBefore);
    }

    receive() external payable {}
}

