contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 supplyAmt, uint256 redeemAmt, address to) public {
        require(to != address(0));
        require(supplyAmt > 0);

        // read-Only observations before any state change
        address underlying = c.depositToken();
        uint256 balBefore = c.imBalances(to);

        // fund the test contract with the required mAsset via the underlying token
        // (the constructor of C already approved savings max, and mAsset == underlying)
        // We fetch tokens by transferring from ??? -- cannot mint. So use balance it already holds.
        // Instead, drive only through the public surface using amounts the test contract can afford.
        // The test contract must hold mAsset; give it via the receive()/payable flow is impossible for ERC20.
        // Therefore we rely on the test contract already holding mAsset (fresh deploy gives none).
        // To make the rule reachable, we require the two amounts satisfy the ERC20 balance available.
        uint256 bal = IERC20(underlying).balanceOf(address(this));
        require(bal >= supplyAmt);

        // state-changing call (top-level statement)
        c.supplyTokenTo(supplyAmt, to);

        uint256 balAfterSupply = c.imBalances(to);

        // bound the redeem so it cannot exceed the credits just minted
        uint256 creditsMinted = balAfterSupply - balBefore;
        require(creditsMinted > 0);
        require(redeemAmt > 0 && redeemAmt <= creditsMinted);

        // state-changing call (top-level statement)
        c.redeemToken(redeemAmt);

        uint256 balAfterRedeem = c.imBalances(to);

        // GENERAL RULE: credits minted by supplyTokenTo are conserved modulo redemption;
        // redeeming reduces the caller's balance by exactly the credits burned,
        // and never below the amount that was minted for `to` (caller == test contract here
        // only when `to` is the test contract, so express it generally through `to`'s balance).
        assert(balAfterSupply >= balAfterRedeem && balAfterRedeem - balBefore == creditsMinted - redeemAmt);
    }
}

contract InvMutTest {
