    }

    receive() external payable {}

    function run(uint256 supplyAmt, address to) public {
        require(to != address(0));
        require(supplyAmt > 0);

        // Observe initial public state before any c state change.
        address underlying = c.depositToken();
        uint256 supplyBeforeTo = c.imBalances(to);
        uint256 supplyBeforeCaller = c.imBalances(address(this));
        uint256 mAssetBalBefore = IERC20(c.mAsset()).balanceOf(address(this));

        // Ensure the test contract can fund the required mAsset transfer.
        require(mAssetBalBefore >= supplyAmt);

        // state-changing call: supply for `to`, credits go to `to`
        c.supplyTokenTo(supplyAmt, to);
        uint256 supplyAfterTo = c.imBalances(to);

        // Credits minted for `to` must equal the increase in `to`'s imBalance.
        uint256 creditsMinted = supplyAfterTo - supplyBeforeTo;
        require(creditsMinted > 0);

        // We redeem as the caller, so credits must exist for the caller.
        require(supplyBeforeCaller >= creditsMinted);

        uint256 callBalanceBefore = c.imBalances(address(this));
        uint256 mAssetBalBeforeRedeem = IERC20(c.mAsset()).balanceOf(address(this));

        // state-changing call, top-level: redeem exactly the credits minted
        uint256 actualReturned = c.redeemToken(creditsMinted);
        uint256 callBalanceAfter = c.imBalances(address(this));
        uint256 mAssetBalAfterRedeem = IERC20(c.mAsset()).balanceOf(address(this));

        // GENERAL RULE: redeeming X credits burns exactly X credits from the caller
        // and transfers exactly the returned mAsset amount into the caller's balance.
        assert(
            callBalanceBefore - callBalanceAfter == creditsMinted &&
            mAssetBalAfterRedeem - mAssetBalBeforeRedeem == actualReturned &&
            supplyAfterTo - supplyBeforeTo == creditsMinted
        );
    }
}

