contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mAssetAmount) public {
        // Precondition: mAssetAmount > 0 (redeem with zero is trivially true and not meaningful)
        require(mAssetAmount > 0, "amount must be positive");

        // Set up: supply some mAssets to the test contract so that redeemToken has something to redeem.
        // supplyTokenTo increments imBalances[to] by creditsIssued from savings.depositSavings.
        c.supplyTokenTo(mAssetAmount, address(this));

        // Read the caller's credit balance before the redeem.
        uint256 creditsBefore = c.imBalances(address(this));

        // Make the deciding call. redeemToken returns the actual mAssets received by the caller.
        uint256 mAssetsActual;
        bool reverted;
        try c.redeemToken(mAssetAmount) returns (uint256 actual) {
            mAssetsActual = actual;
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the caller's credit balance after the redeem.
        uint256 creditsAfter = c.imBalances(address(this));

        // General rule: if the call succeeds, then the caller's imBalances decreased by exactly the
        // credits burned by savings.redeemUnderlying (which is stored in creditsBefore - creditsAfter)
        // and the returned mAssetsActual equals that underlying amount (since redeemUnderlying returns
        // creditsBurned and the actual mAssets received equals the same amount in this contract's logic).
        if (!reverted) {
            // creditsBurned is the difference in credits (safe: creditsAfter <= creditsBefore due to subtraction in contract)
            // The contract does: imBalances[msg.sender] -= creditsBurned; mAssetsActual = balanceAfter - balanceBefore;
            // So the credits decrease should equal mAssetsActual obtained.
            assert(creditsBefore - creditsAfter == mAssetsActual);
        } else {
            // If it reverted, the credit balance must be unchanged.
            assert(creditsAfter == creditsBefore);
        }
    }

    receive() external payable {}
}

