        require(supplyAmount > 0 && supplyAmount <= 1e30, "supply amount in range");
        require(beneficiary != address(0), "beneficiary set");
        require(redeemAmount <= 1e30, "redeem amount in range");

        // Give the test contract the mAsset needed for the supply, then approve c.
        IERC20 mAsset = IERC20(c.depositToken());
        mAsset.safeApprove(address(c), type(uint256).max);

        // ---- Setup: supply mAsset to the beneficiary and observe the credited balance.
        uint256 balanceBefore = c.balanceOfToken(beneficiary);
        c.supplyTokenTo(supplyAmount, beneficiary);
        uint256 balanceAfter = c.balanceOfToken(beneficiary);

        // Rule A: supplying credits exactly the amount reported by the exchange rate,
        // on top of the beneficiary's previous balance, and never reduces it.
        require(
            balanceAfter >= balanceBefore,
            "supply did not reduce balance"
        );

        // ---- Rule B: redeeming more than the caller holds must revert.
        uint256 ownBalance = c.balanceOfToken(address(this));
        bool redeemReverted;
        if (ownBalance == 0) {
            try c.redeemToken(redeemAmount) {
                redeemReverted = false;
            } catch {
                redeemReverted = true;
            }
        }

        // ---- Rule C (main rule): for any successful redeem call, the returned
        // mAssetsActual equals exactly the increase in c's mAsset balance, and the
        // caller's imBalance decreases (credits burned <= previous balance).
        uint256 cBalanceBefore = mAsset.balanceOf(address(c));
        uint256 senderBalanceBefore = mAsset.balanceOf(address(this));
        uint256 imBalanceBefore = c.balanceOfToken(address(this));

        bool reverted;
        uint256 returnedAmount;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            returnedAmount = actual;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 cBalanceAfter = mAsset.balanceOf(address(c));
            uint256 senderBalanceAfter = mAsset.balanceOf(address(this));
            uint256 imBalanceAfter = c.balanceOfToken(address(this));
            assert(
                cBalanceAfter <= cBalanceBefore &&
                cBalanceBefore - cBalanceAfter == returnedAmount &&
                senderBalanceAfter == senderBalanceBefore + returnedAmount &&
                imBalanceAfter <= imBalanceBefore
            );
        } else {
            assert(
                imBalanceBefore == 0 || redeemAmount > imBalanceBefore
            );
        }
    }

    receive() external payable {}
}

