contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(user != address(0), "user zero");
        require(supplyAmount > 0, "no supply");
        require(redeemAmount > 0, "no redeem");

        // Move enough mAsset into the test contract so supplyTokenTo can pull it.
        address mAssetAddr = c.depositToken();
        IERC20 mAsset = IERC20(mAssetAddr);
        uint256 bal = mAsset.balanceOf(address(this));
        require(bal >= supplyAmount, "insufficient mAsset for supply");
        mAsset.safeApprove(address(c), supplyAmount);

        c.supplyTokenTo(supplyAmount, user);
        uint256 credits = c.imBalances(user);
        require(credits > 0, "no credits issued");

        uint256 redeemableUnderlying = c.balanceOfToken(user);
        require(redeemableUnderlying > 0, "no redeemable underlying");

        // Choose the amount of underlying to redeem.
        // The savings contract's redeemUnderlying() returns the credits burned.
        // If redeemAmount is <= redeemableUnderlying, the credits burned should be <= credits,
        // so c's subtraction cannot underflow and the call should succeed.
        // If redeemAmount > redeemableUnderlying, the savings contract may burn more credits than the user owns,
        // causing c's imBalances[msg.sender] -= creditsBurned to underflow and revert.
        bool reverted;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            reverted = false;
            // On success, spent credits cannot exceed the user's total credits.
            assert(c.imBalances(user) <= credits);
        } catch {
            reverted = true;
            // On revert, the user's credits are unchanged.
            assert(c.imBalances(user) == credits);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(user != address(0), "user zero");
        require(supplyAmount > 0, "no supply");
        require(redeemAmount > 0, "no redeem");

        // Set up: supply mAsset on behalf of `user` so they have credits.
        // The test contract needs the mAsset tokens and must approve c to pull them.
        address mAssetAddr = c.depositToken();
        IERC20 mAsset = IERC20(mAssetAddr);
        uint256 bal = mAsset.balanceOf(address(this));
        require(bal >= supplyAmount, "insufficient mAsset for supply");
        mAsset.approve(address(c), supplyAmount);

        c.supplyTokenTo(supplyAmount, user);

        uint256 creditsBefore = c.imBalances(user);
        require(creditsBefore > 0, "no credits issued");

        // Read the underlying value of those credits through the public balanceOfToken view.
        uint256 valueBefore = c.balanceOfToken(user);
        require(valueBefore > 0, "no redeemable underlying");

        // Decide: redeem `redeemAmount` of underlying.
        // If redeemAmount <= valueBefore, the credits burned should be <= creditsBefore,
        // so c's subtraction cannot underflow and the call should succeed.
        // If redeemAmount > valueBefore, the savings contract may burn more credits than user owns,
        // causing imBalances[msg.sender] -= creditsBurned to underflow and revert.
        bool reverted;
        try c.redeemToken(redeemAmount) returns (uint256 /* actual */) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(user);

        if (redeemAmount <= valueBefore) {
            // For a redeem within the user's credit-backed value, it must succeed and
            // the user's credit balance must not increase.
            assert(!reverted);
            assert(creditsAfter <= creditsBefore);
        } else {
            // For an over-redemption that would burn more credits than the user owns,
            // the call must revert and the user's credits must be unchanged.
            assert(reverted);
            assert(creditsAfter == creditsBefore);
        }
    }

    receive() external payable {}
}

