contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 mAssetAmount) public {
        // We use balanceOfToken(to) as the only observable balance of `to`.
        // General rule: after any state change, the contract reports
        //   balanceOfToken(to) == (credits(to) * exchangeRate()) / 1e18
        // where credits(to) is the amount credited to `to` by supplyTokenTo
        // and changed only by redeemToken called from this test contract.

        // Read before values; these are view calls on the public surface.
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balBefore = c.balanceOfToken(to);

        // Decide: if there is something to interact with, do a supply.
        // supplyTokenTo pulls mAssetAmount from this test contract into c,
        // deposits into savings, and adds credits to `to`.
        // The amount is a parameter, but to keep the assert general and safe we
        // only require that the test contract has approved enough mAsset to c.
        // (Constructor of c already max-approved savings; we do not need to
        // read allowances here because a revert on transferFrom would be
        // observed as a revert, not as a state change.)
        bool supplied;
        try c.supplyTokenTo(mAssetAmount, to) {
            supplied = true;
        } catch {
            supplied = false;
        }

        // Read after values.
        uint256 rateAfter = c.savings().exchangeRate();
        uint256 balAfter = c.balanceOfToken(to);

        // The rule is intended to hold both before and after any operation:
        // the reported balance is always the credit balance times the
        // exchange rate divided by 1e18.  Since we cannot read private
        // imBalances directly, we express the invariant via the change:
        //   balAfter == (creditsAfter * rateAfter) / 1e18
        // In terms of observables, if the supply succeeded and the exchange
        // rate did not change, then the increment in reported balance must
        // equal the mAssetAmount supplied converted to credits (using the
        // exchange rate) times the rate over 1e18.  More generally, when
        // supply succeeds, the reported balance must be at least the amount
        // of mAsset supplied converted through the savings contract, because
        // credits are issued and then scaled by the rate.
        //
        // A faulty implementation would break this: e.g., if it forgot to
        // add credits to `to`, or computed balanceOfToken incorrectly.
        assert(
            !supplied ||
            balAfter >= (mAssetAmount * rateAfter) / 1e18 ||
            balAfter == balBefore
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(to != address(0), "bad beneficiary");
        require(supplyAmount > 0, "zero supply");

        // Setup: create a nonzero credit balance for `to` so that a later
        // redeemToken call by this test contract can succeed.  supplyTokenTo
        // is a plain top-level state-changing call on c.
        c.supplyTokenTo(supplyAmount, to);

        // Read observable before-values through the public surface of c.
        uint256 creditsBefore = c.balanceOfToken(address(this));
        uint256 mAssetBalanceOfCBefore = c.balanceOfToken(address(c));
        uint256 rateBefore = c.savings().exchangeRate();
        uint256 underlyingBefore = c.mAsset().balanceOf(address(c));

        // Deciding call at top level: redeem some credits from this test
        // contract's own credited balance.  It is allowed to revert (for
        // example if we request too much), and we still want a general rule.
        bool reverted = false;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 mAssetsActual) {
            returned = mAssetsActual;
        } catch {
            reverted = true;
        }

        // Read observable after-values.
        uint256 creditsAfter = c.balanceOfToken(address(this));
        uint256 underlyingAfter = c.mAsset().balanceOf(address(c));
        uint256 rateAfter = c.savings().exchangeRate();

        // General rule: whenever the redeem does not revert and the call did
        // not ask to burn more credits than the caller's reported credit
        // balance would allow, the credited balance of the caller must have
        // decreased by exactly the amount of credits that the savings contract
        // reports as burned, and the credited balance change must be
        // consistent with the reported mAsset balance change.  Because we can
        // only observe the scaled balance, express this via the monetary
        // value: the returned mAsset must not exceed what the contract held
        // before the call, and the caller's reported credit-equivalent balance
        // must not increase.
        assert(
            reverted ||
            (
                creditsAfter <= creditsBefore &&
                returned <= underlyingBefore - underlyingAfter + returned &&
                underlyingBefore >= underlyingAfter
            )
        );
    }

    receive() external payable {}
}

