contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to) public {
        require(to != address(0), "zero beneficiary");

        IERC20 mAsset = IERC20(c.depositToken());

        uint256 creditsBefore = c.imBalances(to);

        // Read-only measurement of the yield source's view of credit issuance is not possible
        // for an arbitrary amount, so the rule is stated directly in terms of the
        // observable post-call credit balance: it must equal the pre-call credit balance
        // plus the credits the yield source actually issued for the supplied amount.
        // The deciding call is `supplyTokenTo` itself; its state mutation is captured by
        // comparing imBalances[to] before and after (above and below).
        c.supplyTokenTo(amount, to);

        uint256 creditsAfter = c.imBalances(to);

        // The only way credits can be minted is by the savings contract returning credits.
        // We can observe the amount supplied and assert the credit increase is consistent
        // with the savings contract's own exchange-rate accounting: the underlying value of
        // the newly minted credits must equal the supplied amount (within rounding).
        uint256 exchangeRate = c.savings().exchangeRate();
        uint256 underlyingValue = (creditsAfter - creditsBefore) * exchangeRate / 1e18;

        assert(underlyingValue <= amount && amount - underlyingValue <= 1e18);
    }

    receive() external payable {}
}

