    function run(uint256 depositAmount, uint256 redeemAmount, uint256 exchangeRate) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(redeemAmount > 0, "redeem must be positive");

        // Supply tokens to this contract so it has credits to redeem.
        c.supplyTokenTo(depositAmount, address(this));

        uint256 creditsBefore = c.imBalances(address(this));
        uint256 mAssetBefore = IERC20(c.depositToken()).balanceOf(address(this));

        uint256 creditsBurned;
        bool reverted;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            creditsBurned = 0; // will be inferred from balance change
