        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 mAssetAfter = IERC20(c.depositToken()).balanceOf(address(this));
            // Credits burned is the decrease in imBalances.
            creditsBurned = creditsBefore - creditsAfter;
            // The mAssets actually received equal the increase in this contract's mAsset balance.
            uint256 mAssetsActual = mAssetAfter - mAssetBefore;
            assert(creditsBurned > 0 && creditsAfter == creditsBefore - creditsBurned && mAssetsActual == mAssetAfter - mAssetBefore);
        } else {
            // If it reverted, no state change should have occurred.
            assert(c.imBalances(address(this)) == creditsBefore);
        }
    }

    receive() external payable {}
}

