    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        address me = address(this);
        address token = c.depositToken();

        // Fund this test contract with enough mAsset so supplyTokenTo can pull supplyAmount tokens.
        // Read the balance before any interaction so we can compute the exact amount transferred.
        IERC20(token).balanceOf(me);

        // The checker funds this contract externally; clamp supplyAmount to available balance so
        // a valid setup exists but the contract's own semantics still drive the rule.
        uint256 available = IERC20(token).balanceOf(me);
        uint256 supply = supplyAmount % (available + 1);

        c.supplyTokenTo(supply, me);

        uint256 creditsBefore = c.imBalances(me);
        uint256 tokenBefore = IERC20(token).balanceOf(address(c));

        bool reverted;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(me);
        uint256 tokenAfter = IERC20(token).balanceOf(address(c));

        // General rule: redeemToken only succeeds when the caller's credits exactly cover the
        // redemption, and when it succeeds the returned amount equals the actual mAsset outflow
        // from c (tokenBefore - tokenAfter). When it fails, c's token balance and the caller's
        // credits are unchanged.
        if (reverted) {
            assert(creditsAfter == creditsBefore && tokenAfter == tokenBefore);
        } else {
            assert(returned == tokenBefore - tokenAfter && creditsBefore >= creditsAfter);
        }
    }

    receive() external payable {}
}

