        // Fund this test contract with enough mAsset so supplyTokenTo can pull supplyAmount tokens.
        uint256 available = asset.balanceOf(me);
        uint256 supply = supplyAmount % (available + 1);

        // Ensure the supplied amount is credited to this test contract.
        c.supplyTokenTo(supply, me);

