        // 2. The caller's credits decrease by exactly the returned amount.
        // 3. c always keeps enough mAsset to cover the redeemed amount.
        assert(returned == tokenBefore - tokenAfter && creditsBefore - creditsAfter == returned);
    }

    receive() external payable {}
}

