contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mAssetAmount, address to, uint256 supplyAmount) public {
        require(mAssetAmount > 0);
        require(supplyAmount > 0);

        IERC20 mAsset = c.mAsset();
        uint256 exchangeRate = c.savings().exchangeRate();

        mAsset.approve(address(c), supplyAmount);
        uint256 balBefore = c.balanceOfToken(to);
        uint256 priorCredits = exchangeRate == 0 ? 0 : (balBefore * 1e18) / exchangeRate;

        c.supplyTokenTo(supplyAmount, to);

        uint256 balAfter = c.balanceOfToken(to);

        assert(balAfter >= balBefore);
        assert((balAfter - balBefore) * 1e18 >= supplyAmount * exchangeRate - exchangeRate);
        assert((balAfter - balBefore) * 1e18 <= supplyAmount * exchangeRate + exchangeRate);
        assert(c.imBalances(to) >= priorCredits);
    }
}
